import { Suspense } from 'react'
import { getRelatedProducts } from '@/lib/data'

async function RelatedProducts() {
  const relatedProducts = await getRelatedProducts()

  return (
    <section>
      <h2>Related products</h2>
      <ul>
        {relatedProducts.map((product) => (
          <li key={product}>{product}</li>
        ))}
      </ul>
    </section>
  )
}

export default async function ProductPage() {
  return (
    <main>
      <h1>Premium Widget</h1>
      <p>A durable widget for everyday projects.</p>
      {/*
        Related products live behind a Suspense boundary so they are a
        deferred prerender segment. The default route prefetch only fetches
        the prerendered shell (up to this boundary), keeping the related
        products out of the default product-page prefetch. The featured
        product link opts into a full prefetch (prefetch) so this deferred
        segment is warmed and ready immediately on navigation.
      */}
      <Suspense fallback={<section aria-busy="true" />}>
        <RelatedProducts />
      </Suspense>
    </main>
  )
}

